import{_ as o,C as e,c as s,o as r,aj as l,G as a,w as h}from"./chunks/framework.Bfdr4H5E.js";const g="/sk/images/TradingView-Initial-View.webp",c="/sk/images/TV-Status-Market-Updates.webp",d="/sk/images/TradingView-Status-Settings.webp",u="/sk/images/TradingView-Symbol-Info.webp",p="/sk/images/TradingView-Chart-Look.webp",m="/sk/images/TradingView-Scale-Price-Chart.webp",w="/sk/images/TradingView-FinalLook.webp",C=JSON.parse('{"title":"TradingView – Chart Area Basics & Settings","description":"","frontmatter":{"outline":"deep","prev":{"text":"Charting Platform","link":"/trading-with-pav/charting-platform"},"next":{"text":"TradingView – How to use Drawing Tools","link":"/trading-with-pav/tradingview-how-to-use-drawing-tools"}},"headers":[],"relativePath":"trading-with-pav/tradingview-chart-area-basics-settings.md","filePath":"trading-with-pav/tradingview-chart-area-basics-settings.md"}'),b={name:"trading-with-pav/tradingview-chart-area-basics-settings.md"};function y(f,t,k,S,v,T){const n=e("GraphComment"),i=e("ClientOnly");return r(),s("div",null,[t[0]||(t[0]=l('<h1 id="tradingview-–-chart-area-basics-settings" tabindex="-1">TradingView – Chart Area Basics &amp; Settings <a class="header-anchor" href="#tradingview-–-chart-area-basics-settings" aria-label="Permalink to &quot;TradingView – Chart Area Basics &amp; Settings&quot;">​</a></h1><p>In this article will setup the TradingView – Chart Area Basics &amp; Settings for better viewing through exploring the setting and favorite the drawing tools, chart styles, use Watchlist and connect Trading Panel to paper trading for learning period.</p><p>Also whatever settings are set here are also used on this website chart images for all articles.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#first-look">First Look.</a></li><li><a href="#setting-the-chart">Setting the Chart.</a><ul><li><a href="#selecting-a-stock-and-saving-the-layout">Selecting a Stock and Saving the Layout.</a></li><li><a href="#setting-up-trading-panel-to-paper-trading">Setting up Trading Panel to Paper Trading.</a></li><li><a href="#chart-area">Chart Area</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="first-look" tabindex="-1">First Look. <a class="header-anchor" href="#first-look" aria-label="Permalink to &quot;First Look.&quot;">​</a></h2><p>By Default it will be AAPL (Apple Stock) of NASDAQ Exchange with Daily Timeframe. If its not no worries will set it to something different for now so we can set up with no difficulties.</p><h2 id="setting-the-chart" tabindex="-1">Setting the Chart. <a class="header-anchor" href="#setting-the-chart" aria-label="Permalink to &quot;Setting the Chart.&quot;">​</a></h2><h3 id="selecting-a-stock-and-saving-the-layout" tabindex="-1">Selecting a Stock and Saving the Layout. <a class="header-anchor" href="#selecting-a-stock-and-saving-the-layout" aria-label="Permalink to &quot;Selecting a Stock and Saving the Layout.&quot;">​</a></h3><p>So now do the following steps in your TradingView Browser tab.</p><ol><li>In the top Menu there is <strong>symbol search</strong> click on it and type in that search “SBIN”. After typing this you should see 3 Scripts select the one that says “State Bank of India” which has on the right side stock exchange name “NSE”.</li><li>Next Click on the <strong>Timeframe</strong> button in the top panel and select “<strong>1 Day</strong>” if already set no need to change.</li><li>In the top menu right side there is “<strong>Unnamed</strong>” clicking on it will save the chart. Whenever you want to save changes to the chart you want always to load when you open TradingView you must click here.</li><li>After saving click on the arrow pointing down after “<strong>Unnamed</strong>” you will get a dropdown menu select Rename give whatever name you want for this chart layout. It will Replace Unnamed. So when you want to save next time click on the name you created.</li><li>There is auto save but its risky cuz any unwanted changes might also get saved. If you are fine with that go ahead.</li></ol><h3 id="setting-up-trading-panel-to-paper-trading" tabindex="-1">Setting up Trading Panel to Paper Trading. <a class="header-anchor" href="#setting-up-trading-panel-to-paper-trading" aria-label="Permalink to &quot;Setting up Trading Panel to Paper Trading.&quot;">​</a></h3><ol><li>Click on “<strong>Trading Panel</strong>” in the bottom menu/panel.</li><li>There will be a list of brokers in that hover on “<strong>Paper Trading</strong>” and you will see connect button click on it.</li><li>There will be a pop up to connect with disclaimer mentioning<br> “Paper Trading (also known as simulated trading) lets you practice buying and selling securities. Technically it is same as real trading, but with no risk of losing money. Our system tracks your orders and you can see how much Profit or Loss you have on your account, and evaluate how good you are at trading!”</li><li>Clicking on connect will connect it to order window. You will see the account balance 1 Lakh.<br> And the Panel is populated with Position, Orders, History, Account History and Trading Journal.</li><li>It is highly recommended to set the account balance to whatever real money you will be introducing to the market later. You will learn later in the course &amp; articles but until then let it be 1 Lakh.</li><li>Clicking back on “<strong>Trading Panel</strong>” now named “<strong>Paper Trading</strong>” will minimize the panel.</li></ol><h3 id="chart-area" tabindex="-1">Chart Area <a class="header-anchor" href="#chart-area" aria-label="Permalink to &quot;Chart Area&quot;">​</a></h3><p><img src="'+g+'" alt="TradingView-Initial-View"></p><h4 id="status-line" tabindex="-1">Status line <a class="header-anchor" href="#status-line" aria-label="Permalink to &quot;Status line&quot;">​</a></h4><p>By now your chart should look like the above image. The Status line marked in the image shows that State Bank of India is the script selected with 1D tell us its Daily Chart and NSE is exchange. After NSE there is -≈ symbol. Clicking on it will reveal the following.</p><p><img src="'+c+'" alt="TV-Status-Market-Updates"></p><p>As you can see in the image it tells us that Market is closed and gives information on when it will open and close with pre and post market timings. But the main information is the second part “<strong>One update every 5 seconds</strong>” which is good for trading live. It would be bad if it was <strong>15 min</strong> Update then we would have to get their Paid plan. So next time check this crucial information on any other script.</p><p><img src="'+d+'" alt="TradingView-Status-Settings"></p><p><img src="'+u+'" alt="TradingView-Symbol-Info"></p><p>One more thing if you want to see the Symbol details then hover on Status line click on three dots a menu will appear as seen in above left image. Click on “<strong>Symbol Info</strong>” a dialog will appear with info regarding the symbol as shown in above right image.</p><p>You can get info like symbol name i.e. SBIN (short name to search this script in “<strong>search symbol</strong>“) description, type, Exchange, Tick Size</p><h4 id="buy-sell-buttons" tabindex="-1">Buy/Sell buttons <a class="header-anchor" href="#buy-sell-buttons" aria-label="Permalink to &quot;Buy/Sell buttons&quot;">​</a></h4><p>Next is OHLC in status line i.e. self explanatory. Below the status line there are 2 buttons Red is SELL button and Blue is BUY button. In the middle of the button is Spread which is difference in ASK and BID. Spread formula is Bid – Ask. In the above example it is 0.00.</p><h4 id="indicator" tabindex="-1">Indicator <a class="header-anchor" href="#indicator" aria-label="Permalink to &quot;Indicator&quot;">​</a></h4><p>The third one is the Indicator named Volume. This Volume indicator shows executed volume below every candle. The Volume bar at the bottom is red if the candle above it is bearish and green if the candle above is bullish. But this color scheme is not true as you will learn later that there are both parties involve buyers and sellers. There is no such thing as this candle has only buyers and this has only sellers.</p><p>So hover on volume indicator you will see settings gears icon click on it (From now on any time you want to change indicator settings you have to hover over that indicator name and change settings and save chart layout).</p><p>After settings window appear click on “<strong>style</strong>” and change the color of “<strong>growing</strong>” to any color you like give the same color to “<strong>falling</strong>“. Then tick the Volume MA, click on color and change the opacity to 15. Now click on the square icon on the right side of color and select “<strong>area</strong>” then go to the “<strong>inputs</strong>” tab left of the “<strong>style</strong>” change the “<strong>MA length</strong>” to 10 and click OK button. Save the chart so this indicator settings are saved.</p><p><img src="'+p+'" alt="TradingView-Chart-Look"></p><p>This is how your chart should look by now. Next will get into the Main Settings.</p><h4 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h4><p>In the top menu on the right side after search icon there is settings with gear icon click on it. “<strong>Chart Settings</strong>” should pop up. On the left side you can first see “<strong>Symbol</strong>” highlighted and setting for symbol on right. For “<strong>Symbol</strong>” on right side change the wick to “Black color”.</p><p>Next click on “<strong>Status Line</strong>” in left side and for status line change the “<strong>Title</strong>” Description to “<strong>Ticker and description</strong>” and tick “<strong>Volume</strong>” on so that it may appear in the status line.<br> Nothing to change in “<strong>Scales</strong>“. Check if “<strong>Countdown to bar close</strong>” is ticked.</p><p>Next is “<strong>Appearance</strong>” change the grid lines to “<strong>None</strong>“. Change the Scales “<strong>Text</strong>” font which is 12 to anything your chart is readable and pleasing to eyes. Below “<strong>Text</strong>” there is “<strong>Lines</strong>” change the opacity from 0 to 15.</p><p>Now click on “<strong>Trading</strong>” and tick “<strong>Play sound for executions</strong>“. Above “Play sound for executions” is “<strong>Instant orders placement</strong>” which should be always <strong>off</strong> otherwise your orders go market order only.</p><p>Nothing to change in “<strong>Events</strong>“. Click <strong>OK</strong> and save the chart layout. Now go to “<strong>Timeframe</strong>” in top menu and change it to 15 mins. As you should notice the 15 min chart which is intraday chart doesn’t show day (session) break i.e. when the day closes and next day starts. So again open the settings and click on “<strong>Events</strong>” there is a setting called “<strong>Session breaks</strong>” tick it <strong>ON</strong> and change the color grey next to the white color. Then click on the square box right to color and make it “<strong>Dotted Line</strong>“. Press <strong>OK</strong> and save the “<strong>chart Layout</strong>“. Now one last setting, go to bottom right corner there is settings gear below the price axis click on the gear and select “<strong>Scale price chart only</strong>“. See the image below if you don’t find the setting’s.</p><p><img src="'+m+'" alt="TradingView-Scale-Price-Chart"></p><p>Now save the chart and it should look like the following image</p><p><img src="'+w+'" alt="TradingView-FinalLook"></p><p>In next article will see how to draw and mark favorite drawing tools to access fast. That’s it for this article.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',41)),a(i,null,{default:h(()=>[a(n)]),_:1})])}const _=o(b,[["render",y]]);export{C as __pageData,_ as default};
